        // Test case 7: Count down to zero from maximum
        #1024; // Wait for the counter to reach zero
        if (tc !== 1'b1) errors = errors + 1; // tc should be high when count reaches 0

        // Test case 8: Load while at zero
        load = 1; data = 10'd10; #10;
        load = 0; #10; // Start counting down
        if (tc !== 1'b0) errors = errors + 1; // tc should be low while counting down

        // Test case 9: Load with zero again
        load = 1; data = 10'd0; #10;
        if (tc !== 1'b1) errors = errors + 1; // tc should be high immediately after loading 0

        // Final check
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
